def update_in(coll, path, update, default=None):
    """Creates a copy of coll with a value updated at path."""
    if not path:
        return update(coll)
    elif isinstance(coll, list):
        copy = coll[:]
        # NOTE: there is no auto-vivication for lists
        copy[path[0]] = update_in(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = coll.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = update_in(copy.get(path[0], current_default), path[1:], update, default)
        return copy


def safe_update_in(coll, path, update, default=None):
    """Like update_in but returns coll unchanged when path is empty."""
    if not path:
        return coll
    elif isinstance(coll, list):
        copy = coll[:]
        copy[path[0]] = safe_update_in(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = coll.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = safe_update_in(copy.get(path[0], current_default), path[1:], update, default)
        return copy
